    override fun playerEnchantItem(event: GameEvent.PlayerEnchantItem): Boolean = Native.call(id, 71, { w ->
        putPlayerRef(w, event.player)
        putBlockRef(w, event.block)
        putItemData(w, event.item)
        w.map(event.enchantments, { x0 -> w.string(x0) }) { x0 -> w.int(x0) }
        w.int(event.cost)
    }) { r ->
        val cancelled = r.bool()
        event.cost = r.int()
        cancelled
    }

    override fun furnaceSmelt(event: GameEvent.FurnaceSmelt): Boolean = Native.call(id, 72, { w ->
        putBlockRef(w, event.block)
        putItemData(w, event.source)
        putItemData(w, event.result)
    }) { r ->
        val cancelled = r.bool()
        event.result = takeItemData(r)
        cancelled
    }

    override fun serverListPing(event: GameEvent.ServerListPing): Boolean = Native.call(id, 73, { w ->
        w.string(event.address)
        w.string(event.description)
        w.int(event.online)
        w.int(event.maxPlayers)
        w.bool(event.hidePlayers)
    }) { r ->
        val cancelled = r.bool()
        event.description = r.string()
        event.online = r.int()
        event.maxPlayers = r.int()
        event.hidePlayers = r.bool()
        cancelled
    }
}
